<?php
require __DIR__ . '/functions.php';
$lines = cart_products(); if (!$lines) { header('Location: index.php?view=cart'); exit; }
$subtotal = array_reduce($lines, fn($sum, $line) => $sum + $line['price'] * $line['quantity'], 0); $method = $_POST['delivery_method'] ?? 'À domicile'; $rates = ['Bureau' => 400, 'À domicile' => 700]; $shipping = $rates[$method] ?? 700; $error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') { check_csrf(); $required = ['full_name','phone','wilaya','commune']; foreach ($required as $field) if (trim($_POST[$field] ?? '') === '') $error = 'Please complete every delivery field.'; if (!$error) { $statement = db()->prepare('INSERT INTO orders (full_name, phone, wilaya, commune, delivery_method, shipping_cost, total, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?)'); $statement->execute([trim($_POST['full_name']), trim($_POST['phone']), trim($_POST['wilaya']), trim($_POST['commune']), $method, $shipping, $subtotal + $shipping, 'New']); $orderId = db()->lastInsertId(); $item = db()->prepare('INSERT INTO order_items (order_id, product_id, quantity, unit_price) VALUES (?, ?, ?, ?)'); foreach ($lines as $line) { $item->execute([$orderId, $line['id'], $line['quantity'], $line['price']]); db()->prepare('UPDATE products SET stock = GREATEST(stock - ?, 0) WHERE id = ?')->execute([$line['quantity'], $line['id']]); } $_SESSION['cart'] = []; header('Location: checkout.php?success=' . $orderId); exit; } }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Checkout | Lissi</title><link rel="stylesheet" href="style.css"></head><body><header class="header shell"><a class="brand" href="index.php"><img src="assets/logo.jpeg" alt="Lissi"><span>LISSI</span></a><a class="bag" href="?">Cash on delivery</a></header><main class="section shell"><?php if (isset($_GET['success'])): ?><div class="notice"><b>Order received.</b> We will call you shortly to confirm order #<?= e($_GET['success']) ?>.</div><a class="dark" href="index.php">Continue shopping</a><?php else: ?><p class="eyebrow">Almost yours</p><h2>Delivery details</h2><p>We will call to confirm your order before dispatch.</p><?php if ($error): ?><div class="notice"><?= e($error) ?></div><?php endif; ?><form class="form" method="post"><input type="hidden" name="csrf" value="<?= csrf() ?>"><label>Full name<input name="full_name" required></label><label>Phone number<input name="phone" type="tel" required></label><div class="form-row"><label>Wilaya<input name="wilaya" required></label><label>Commune<input name="commune" required></label></div><label>Delivery method<select name="delivery_method" onchange="this.form.submit()"><option <?= $method === 'À domicile' ? 'selected' : '' ?>>À domicile</option><option <?= $method === 'Bureau' ? 'selected' : '' ?>>Bureau</option></select></label><div class="summary"><div><span>Subtotal</span><b><?= money($subtotal) ?></b></div><div><span>Delivery</span><b><?= money($shipping) ?></b></div><div class="total"><span>Total</span><b><?= money($subtotal + $shipping) ?></b></div></div><button class="dark" type="submit">Place COD order →</button></form><?php endif; ?></main></body></html>
